/**
 * portfolio.ts — the consumer-side contract gate for `src/data/portfolio.json`.
 *
 * `portfolio.json` is GENERATED by `observatory export --portfolio` in the
 * dev-observatory control plane — the single place project descriptions are
 * edited — and committed here (design decision D2: a committed generated file,
 * not a fetch or prebuild script, so CI stays hermetic and the human review gate
 * on content survives). This module is the ONLY reader of that JSON: it
 * Zod-validates the file against the companion plan's §5d schema at build time,
 * so any producer/consumer drift fails `astro build` LOUDLY (a red Zod error)
 * instead of silently rendering a stale or half-blank Work section (design
 * decision D5, and the workspace wire-shape rule).
 *
 * Never hand-edit `portfolio.json` — edit the observatory registry and re-export.
 */
// `astro/zod` is the Zod instance Astro's content layer already bundles (the same
// import content.config.ts uses); using it keeps zod off the direct dependency list.
import { z } from "astro/zod";
import portfolioData from "./portfolio.json";

/**
 * The five Work-section groups, in the §5d contract order. `non-active`/`hidden`
 * projects are never exported, so they never appear here.
 */
export const GROUPS = [
  "flagship",
  "utility",
  "fun",
  "professional",
  "third-party",
] as const;

export type Group = (typeof GROUPS)[number];

/** An ecosystem cross-reference: a sibling project slug + the relating clause. */
const relatedSchema = z.object({
  slug: z.string(),
  clause: z.string(),
});

/** Derived activity stats — never authored, always computed by the exporter. */
const statsSchema = z.object({
  gap: z.string(),
  tests: z.number(),
  last_commit_days: z.number(),
});

/**
 * One project row of the §5d contract. Nullable fields (`card`, `repo_url`,
 * `live_url`, `contribution`) are ABSENT-as-null, never omitted: a private repo
 * exports `repo_url: null` (the site renders a linkless name), a non-flagship
 * exports `card: null`, and so on. Matching the producer's null discipline
 * exactly is what makes the fail-loud gate meaningful.
 */
const projectSchema = z.object({
  slug: z.string(),
  name: z.string(),
  group: z.enum(GROUPS),
  tag: z.string(),
  blurb: z.string(),
  card: z.string().nullable(),
  proofs: z.array(z.string()),
  relates: z.array(relatedSchema),
  try_it: z.string(),
  repo_url: z.string().nullable(),
  live_url: z.string().nullable(),
  contribution: z.string().nullable(),
  stats: statsSchema,
});

export type PortfolioProject = z.infer<typeof projectSchema>;

const portfolioSchema = z.object({
  // The exporter opens the file with a do-not-hand-edit marker; accept but ignore it.
  _comment: z.string().optional(),
  version: z.literal(1),
  generated_at: z.string(),
  projects: z.array(projectSchema),
});

// `.parse` throws a ZodError at build time on ANY schema drift (missing field,
// wrong type, unexpected `group` value). That thrown error is the fail-loud gate:
// a producer change the consumer doesn't understand turns the deploy red, never
// stale-but-green. THIS LINE is the contract between the two repos.
const portfolio = portfolioSchema.parse(portfolioData);

/** ISO-8601 timestamp of the export that produced the committed JSON. */
export const GENERATED_AT: string = portfolio.generated_at;

/** All exported projects, in export order. */
export const PROJECTS: PortfolioProject[] = portfolio.projects;

/** Projects in one group, preserving the export's ordering. */
export function byGroup(group: Group): PortfolioProject[] {
  return PROJECTS.filter((project) => project.group === group);
}

/**
 * Per-group counts PINNED to the operator's curated portfolio list (plan §9). A
 * mismatch means the observatory export changed the display set — intentionally
 * (a project added/removed/re-tagged, or a `public` flip) or as a regression. In
 * BOTH cases the build fails LOUDLY here so a human confirms the new shape before
 * the site ships, rather than the Work section silently gaining or losing a card.
 *
 * To legitimately change the set: update these pins in the SAME commit as the
 * registry change that moved a project in or out of the public export.
 */
export const EXPECTED_GROUP_COUNTS: Record<Group, number> = {
  flagship: 3,
  utility: 13,
  fun: 6,
  professional: 3,
  "third-party": 2,
};

for (const group of GROUPS) {
  const actual = byGroup(group).length;
  const expected = EXPECTED_GROUP_COUNTS[group];
  if (actual !== expected) {
    throw new Error(
      `portfolio.json group "${group}" has ${actual} project(s), expected ${expected}. ` +
        `The observatory export changed the display set. If intentional, update ` +
        `EXPECTED_GROUP_COUNTS in src/data/portfolio.ts in the same commit; ` +
        `otherwise re-run \`observatory export --portfolio\` and investigate.`,
    );
  }
}
